#!/bin/sh
# Build the pinned pjproject as a signaling-only host library set for
# aula-sipd, then write a CMake initial-cache file that links it.
#
# This is the one dependency lane that downloads: it runs only when invoked
# explicitly (make sipd-pjsip). The archive URL and SHA-256 come from
# dependencies/dependency-lock.json and the archive is refused unless its
# digest matches. Everything is written below .work/. An already extracted
# source tree is reused to avoid a multi-minute rebuild; only its patched
# Makefile digest is re-checked, so anyone able to write .work/ can alter it.
set -eu

script_dir=$(CDPATH='' cd -- "$(dirname -- "$0")" && pwd -P)
root=$(CDPATH='' cd -- "$script_dir/../.." && pwd -P)
work=$root/.work
cache_dir=$work/cache/dependencies
build_root=$work/build/pjproject
cmake_cache=$build_root/aula-sipd-pjsip.cmake

fail() {
    echo "build-pjproject-host: $*" >&2
    exit 1
}

for tool in curl tar make shasum python3; do
    command -v "$tool" >/dev/null 2>&1 || fail "$tool is required"
done

pin=$(python3 -B - "$root/dependencies/dependency-lock.json" <<'EOF'
import json, sys
packages = json.load(open(sys.argv[1], encoding="utf-8"))["packages"]
entry = next(item for item in packages if item["name"] == "pjproject")
print(entry["version"].removeprefix("git-"), entry["immutable_url"], entry["archive_sha256"])
EOF
)
set -- $pin
commit=$1
url=$2
digest=$3
archive=$cache_dir/pjproject-$commit.tar.gz
source_dir=$build_root/pjproject-$commit

mkdir -p "$cache_dir" "$build_root"
if [ ! -f "$archive" ]; then
    curl --fail --silent --show-error --location --output "$archive.part" "$url"
    mv -f "$archive.part" "$archive"
fi
actual=$(shasum -a 256 "$archive" | awk '{print $1}')
[ "$actual" = "$digest" ] || fail "archive digest $actual does not match the pinned $digest"

[ -d "$source_dir" ] || tar -xzf "$archive" -C "$build_root"
[ -d "$source_dir/pjlib/build" ] || fail "archive did not contain pjproject-$commit"
sh "$script_dir/prepare-pjproject-signaling.sh" "$source_dir"

# Signaling only: no PJSUA, audio or video devices, codecs, NAT traversal or
# SRTP. TLS uses the host OpenSSL (OPENSSL_PREFIX overrides discovery).
openssl_prefix=${OPENSSL_PREFIX:-}
if [ -z "$openssl_prefix" ] && command -v brew >/dev/null 2>&1; then
    openssl_prefix=$(brew --prefix openssl 2>/dev/null || true)
fi
platform_libraries=
case $(uname -s) in
    Darwin)
        # GNU binutils' ar writes archives that Apple's linker rejects.
        AR=/usr/bin/ar
        RANLIB=/usr/bin/ranlib
        export AR RANLIB
        platform_libraries=";-framework Foundation"
        ;;
esac
(
    cd "$source_dir"
    ./configure --disable-pjsua2 --disable-upnp --disable-libuuid \
        --disable-resample --disable-sound --disable-video --disable-speex-aec \
        --disable-g711-codec --disable-l16-codec --disable-gsm-codec \
        --disable-g722-codec --disable-g7221-codec --disable-speex-codec \
        --disable-ilbc-codec --disable-sdl --disable-ffmpeg --disable-v4l2 \
        --disable-openh264 --disable-vpx --disable-android-mediacodec \
        --disable-darwin-ssl --disable-opencore-amr --disable-silk \
        --disable-opus --disable-bcg729 --disable-lyra --disable-libsrtp \
        --disable-libyuv --disable-libwebrtc \
        ${openssl_prefix:+--with-ssl="$openssl_prefix"} > "$build_root/configure.log" 2>&1 ||
        fail "configure failed; see $build_root/configure.log"
    jobs=${AULA_BUILD_JOBS:-4}
    { make -C pjlib/build -j"$jobs" lib &&
      make -C pjlib-util/build -j"$jobs" lib &&
      make -C pjmedia/build -j"$jobs" pjmedia &&
      make -C pjsip/build -j"$jobs" pjsip pjsip-ua pjsip-simple; } > "$build_root/build.log" 2>&1 ||
        fail "build failed; see $build_root/build.log"
)

# Archives are named lib<name>-<target triple>.a; take the triple from pjlib,
# whose lib directory holds only libpj.
pjlib_archive=$(find "$source_dir/pjlib/lib" -name 'libpj-*.a' -type f | head -n 1)
[ -n "$pjlib_archive" ] || fail "missing libpj archive"
triple=${pjlib_archive##*/libpj-}
triple=${triple%.a}
library() {
    archive_path=$source_dir/$1/lib/lib$2-$triple.a
    [ -f "$archive_path" ] || fail "missing lib$2-$triple.a"
    printf '%s' "$archive_path"
}
if [ -n "$openssl_prefix" ]; then
    ssl_libraries="-L$openssl_prefix/lib;-lssl;-lcrypto"
else
    ssl_libraries="-lssl;-lcrypto"
fi
pjmedia=$(library pjmedia pjmedia)
cat > "$cmake_cache" <<EOF
# Generated by dependencies/scripts/build-pjproject-host.sh for pjproject $commit.
set(AULA_SIPD_ENABLE_PJSIP ON CACHE BOOL "" FORCE)
set(AULA_SIPD_PJSIP_INCLUDE_DIR "$source_dir/pjsip/include" CACHE PATH "" FORCE)
set(AULA_SIPD_PJSIP_UA_LIBRARY "$(library pjsip pjsip-ua)" CACHE FILEPATH "" FORCE)
set(AULA_SIPD_PJMEDIA_LIBRARY "$pjmedia" CACHE FILEPATH "" FORCE)
set(AULA_SIPD_PJSIP_LIBRARIES "$(library pjsip pjsip-simple);$(library pjsip pjsip);$pjmedia;$(library pjlib-util pjlib-util);$(library pjlib pj);$ssl_libraries$platform_libraries" CACHE STRING "" FORCE)
EOF
echo "build-pjproject-host: wrote $cmake_cache"
